#!/bin/sh
# Second round: medal redesign, Korean water station, clean-up edits. Dev tool, not deployed.
SP=/c/Users/jaemi/AppData/Local/Temp/claude/7e6ff043f79a9415/ab92f51c-d44a-48f8-b922-d120aba180a3/scratchpad
G=$SP/marathon/gen
STYLE="Bright contemporary sports photograph made on a modern full-frame digital camera, fast shutter so every person is sharp, low spring morning sun from the side with crisp shadows, clear pale blue sky, clean true-to-life colour and natural skin. No film grain, no haze, no motion blur, no vignette, not cinematic. Everyone wears plain unbranded running clothes in white, black, cobalt blue and a little red. No race bib numbers, no letters, no logos or brand marks on clothing or shoes, no readable signs anywhere."

python -I $SP/tools/gen_image.py --out $G/medal2.png --aspect 4:5 --prompt "Overhead product photograph of a single finisher medal lying flat on smooth pale grey poured concrete, hard low morning sunlight from the upper left casting one sharp clean shadow. Round brushed stainless-steel medal about 7 cm across with a thin raised rim. Its face is divided by one straight raised horizontal bar slightly below the centre, like a finish tape stretched across: above the bar the steel is smooth and brushed, below it a shallow relief of gentle horizontal water ripples. Nothing else on the face: no diagonal lines, no letters, no numbers, no symbols. The ribbon is a woven cobalt blue strap with a thin red centre stripe, loosely curled beside the medal. Crisp, true colour, modern catalogue photograph, no film grain." > $G/medal2.log 2>&1 &

python -I $SP/tools/gen_image.py --out $G/water2.png --aspect 3:2 --prompt "$STYLE Side view at chest height at a roadside water station during a city half marathon in Korea, 50mm lens: a long folding table with rows of white paper cups, three Korean volunteers of different ages (a high-school girl, a man in his fifties, a woman in her thirties) in plain white vests leaning forward and holding cups out at arm's length, two passing Korean runners reaching out and taking cups mid-stride, a little water splashing in frozen droplets. Hands and fingers clearly visible and anatomically natural. Riverside levee road with fresh green spring trees behind, the river on the right." > $G/water2.log 2>&1 &

python -I $SP/tools/gen_image.py --out $G/corral-clean.png --ref $G/corral.jpg --aspect 3:2 --prompt "Edit this photograph and keep everything else exactly as it is: the same people, faces, poses, light and composition. Remove every logo, brand mark, symbol and printed word from all clothing, caps, vests and shoes so every garment is plain. Remove all writing from the buildings, signboards, banners and road signs: make the sign panels blank and plain. Remove the face masks." > $G/corral-clean.log 2>&1 &

python -I $SP/tools/gen_image.py --out $G/pack-clean.png --ref $G/pack.jpg --aspect 3:2 --prompt "Edit this photograph and keep everything else exactly as it is: the same people, faces, poses, light and composition. Make the black tracksuit of the man on the right completely plain black with no stripes on the sleeves or legs. Remove every logo and brand mark from all shirts, shorts and shoes so every garment is plain." > $G/pack-clean.log 2>&1 &

wait
